/*
 * Service Worker（web_app_shell 段階 D。PROJECT.md 第 12 条）。
 *
 * これはテンプレート。自サイトの本番ビルドで vite.config.ts の serviceWorkerPlugin() が
 * 先頭行の MANIFEST を事前保存の一覧に差し替えて dist/sw.js として出力する
 * （先頭行は 1 行の JSON のまま保つ。テストが正規表現で読む）。dev とポータル版には出力しない。
 *
 *   MANIFEST.cache    … キャッシュ名 pjgp-<ビルド ID>。一覧が同じなら同じ名前（無駄な更新が起きない）
 *   MANIFEST.precache … Tier 1。install 時に全部保存する（HTML・JS・CSS・小さな画像など）
 *   MANIFEST.warm     … Tier 2。大きな画像。standalone で開かれたとき（ページから warm が届く）か、
 *                       実際に使われたときに保存する
 *   各要素は { url, rev }。ハッシュ付きのファイルは rev:null（中身が変わると URL が変わる）
 *
 * 取り扱い:
 *   .mp3                   … 介入しない（HTMLAudioElement の Range 要求に対応しないため。オフラインでは無音）
 *   ページ（navigate）      … ネットワーク優先（3 秒で諦めてキャッシュ。無ければキャッシュのホーム）
 *   一覧にある同一オリジン … キャッシュ優先（無ければ取得して保存）
 *   Google Fonts           … 古いものを返しつつ裏で更新（別キャッシュ pjgp-fonts、上限 30 件）
 *   それ以外               … 介入しない（Firebase・AdSense・PeerJS などは素通し）
 *
 * 更新: 新しい版はバックグラウンドで保存を終えて待機し、全タブが閉じたら（standalone なら次回起動で）有効になる。
 * skipWaiting() は呼ばない。有効化のときに名前の違う pjgp-* を消す。通知は出さない。
 * ネットワークから取った HTML はキャッシュへ書き戻さない（キャッシュの HTML と JS の版を揃えたままにするため）。
 */
const CACHE = MANIFEST.cache
const FONT_CACHE = 'pjgp-fonts'
const FONT_LIMIT = 30
const NAV_TIMEOUT_MS = 3000
const KNOWN = new Set([...MANIFEST.precache, ...MANIFEST.warm].map((e) => e.url))
const FONT_HOSTS = new Set(['fonts.googleapis.com', 'fonts.gstatic.com'])

/** この版より前の pjgp-* キャッシュ（フォントは除く） */
async function oldCaches() {
  return (await caches.keys()).filter((name) => name.startsWith('pjgp-') && name !== CACHE && name !== FONT_CACHE)
}

/** ハッシュ付き（rev:null）は中身が変わらないので、前の版のキャッシュにあれば写す（再ダウンロードしない） */
async function reuseFromOld(cache, entry, olds) {
  if (entry.rev !== null) return false
  for (const name of olds) {
    const hit = await (await caches.open(name)).match(entry.url)
    if (hit) {
      await cache.put(entry.url, hit)
      return true
    }
  }
  return false
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE)
    const olds = await oldCaches()
    const need = []
    for (const entry of MANIFEST.precache) {
      // キャッシュ名は一覧（URL とリビジョン）から決まるので、同じ名前のキャッシュにあるものは中身も同じ。
      // SW 本体だけが変わった更新では取り直さない
      if (await cache.match(entry.url)) continue
      if (!(await reuseFromOld(cache, entry, olds))) need.push(entry.url)
    }
    // Tier 2 は取りに行かないが、前の版で保存済みのものは引き継ぐ
    for (const entry of MANIFEST.warm) await reuseFromOld(cache, entry, olds)
    await cache.addAll(need.map((url) => new Request(url, { cache: 'reload' })))
  })())
})

// clients.claim() は呼ばない。最初に登録したページはそのまま（ネットワークで）動かし、次の画面遷移から SW が受け持つ
// （保存は install のときに終わっているので、オフライン対応には影響しない。開いている途中のページの通信を
//   途中から横取りしないため。テストの page.route による通信の差し替えもそのまま効く）
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await oldCaches()) await caches.delete(name)
  })())
})

/** ページの URL をキャッシュのキーへ（/games/x → /games/x/、/games/x/index.html → /games/x/） */
function navKey(url) {
  let path = url.pathname
  if (path.endsWith('/index.html')) path = path.slice(0, -'index.html'.length)
  if (!path.endsWith('/') && !/\.[a-z0-9]+$/i.test(path)) path += '/'
  return path
}

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout')), ms)
    promise.then((v) => { clearTimeout(timer); resolve(v) }, (e) => { clearTimeout(timer); reject(e) })
  })
}

async function handleNavigate(request, url) {
  try {
    return await withTimeout(fetch(request), NAV_TIMEOUT_MS)
  } catch {
    const cache = await caches.open(CACHE)
    return (await cache.match(navKey(url))) ?? (await cache.match('/')) ?? Response.error()
  }
}

async function cacheFirst(request, path) {
  const cache = await caches.open(CACHE)
  const hit = await cache.match(path)
  if (hit) return hit
  const res = await fetch(request)
  if (res.ok && res.status === 200) cache.put(path, res.clone()).catch(() => {})
  return res
}

async function trimFonts(cache) {
  const keys = await cache.keys()
  for (let i = 0; i < keys.length - FONT_LIMIT; i++) await cache.delete(keys[i])
}

async function fontsStaleWhileRevalidate(event) {
  const cache = await caches.open(FONT_CACHE)
  const hit = await cache.match(event.request)
  const update = fetch(event.request).then(async (res) => {
    // フォントの CSS は @import（no-cors）で読まれるので opaque になる。オフラインで字体を保つため、それも保存する
    if (res.ok || res.type === 'opaque') {
      await cache.put(event.request, res.clone())
      await trimFonts(cache)
    }
    return res
  }).catch(() => null)
  if (hit) {
    event.waitUntil(update)
    return hit
  }
  return (await update) ?? Response.error()
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.pathname.toLowerCase().endsWith('.mp3')) return
  const sameOrigin = url.origin === self.location.origin
  if (sameOrigin && request.mode === 'navigate') {
    event.respondWith(handleNavigate(request, url))
    return
  }
  if (sameOrigin) {
    if (KNOWN.has(url.pathname)) event.respondWith(cacheFirst(request, url.pathname))
    return
  }
  if (FONT_HOSTS.has(url.hostname)) event.respondWith(fontsStaleWhileRevalidate(event))
})

let warming = null

/** Tier 2 のうち未保存のものを順に取りに行く（失敗は無視。次の機会にまた試す） */
async function warm() {
  const cache = await caches.open(CACHE)
  for (const entry of MANIFEST.warm) {
    if (await cache.match(entry.url)) continue
    try {
      const res = await fetch(entry.url, { cache: 'reload' })
      if (res.ok) await cache.put(entry.url, res)
    } catch {
      // 通信できなければ諦める
    }
  }
}

self.addEventListener('message', (event) => {
  if (event.data?.type !== 'warm') return
  if (!warming) warming = warm().finally(() => { warming = null })
  event.waitUntil(warming)
})
